ops:
  backupStatus: [apiBackupStatus, ['系統維護']],
  backupNow: [apiBackupNow, ['系統維護']],
/** 備份狀態（系統維護）：是否已排程、最後一次備份、備份資料夾 */
function apiBackupStatus() {
  return { auto: ScriptApp.getProjectTriggers().some(t => t.getHandlerFunction() === 'backupJob'), last: prop_('BACKUP_LAST') || '', folder: prop_('BACKUP_FOLDER_ID') || '', keep: BACKUP_KEEP };
}
/** 立即備份一次（系統維護） */
function apiBackupNow(args, user) { const r = backupNow_(); log_(user.Email, '資料庫備份', '', r); return Object.assign(apiBackupStatus(), r); }
